<?php require_once __DIR__.'/../config.php'; if(!isset($_SESSION['user_id'])){header('Location:/user/login.php');exit;} include __DIR__.'/../header.php';
$st=$pdo->prepare('SELECT c.id cid,c.quantity,p.* FROM cart c JOIN products p ON p.id=c.product_id WHERE c.user_id=?');$st->execute([$_SESSION['user_id']]);$items=$st->fetchAll();$subtotal=0;foreach($items as $i){$subtotal+=$i['price']*$i['quantity'];}$tax=$subtotal*0.05;$total=$subtotal+$tax; ?>
<main class="max-w-4xl mx-auto p-4"><h1 class="text-xl font-bold mb-3">Cart</h1><?php foreach($items as $i): ?><div class="bg-white rounded-lg p-3 mb-2 flex justify-between"><div><?=clean_input($i['name'])?> x <?=$i['quantity']?></div><div class="flex gap-2"><form method="post" action="/app/Controllers/CartController.php"><input type="hidden" name="action" value="dec"><input type="hidden" name="cart_id" value="<?=$i['cid']?>"><button>-</button></form><form method="post" action="/app/Controllers/CartController.php"><input type="hidden" name="action" value="inc"><input type="hidden" name="cart_id" value="<?=$i['cid']?>"><button>+</button></form></div></div><?php endforeach; ?><div class="bg-white p-3 rounded-lg">Subtotal ₹<?=$subtotal?> | Tax ₹<?=number_format($tax,2)?> | Total ₹<?=number_format($total,2)?></div><a href="/user/checkout.php" class="block text-center bg-indigo-600 text-white py-3 rounded-lg mt-3">Proceed to Checkout</a></main>
<?php include __DIR__.'/../bottom.php'; ?>
